 12	)
 13	
 14	// column is one Board column. It is DERIVED, never stored: CONTEXT.md's
 15	// Ready and Blocked are properties of an open issue rather than statuses, so
 16	// nothing can be put into a column — an issue arrives in one by its status and
 17	// its blockers.
 18	type column int
 19	
 20	const (
 21		colReady column = iota
 22		colBlocked
 23		colInProgress
 24		colClosed
 25	)
 26	
 27	// columnCount is how many columns the board has, whatever the width shows.
 28	const columnCount = 4
 29	
 30	var columnNames = [columnCount]string{"Ready", "Blocked", "In progress", "Closed"}
 31	
 32	// minColumnWidth is the narrowest a column is drawn. What does not fit at it
 33	// is paged sideways rather than squeezed (#2, variant E): four columns in an
 34	// 80-column terminal are slivers nobody can read a title in.
 35	const minColumnWidth = 28
 36	
 37	// columnOf derives one issue's column, one branch per clause.
 38	//
 39	// in_progress is asked BEFORE the blocker count, and that order is the rule
 40	// rather than a detail of it: started work that is stuck is still started, so
 41	// a blocked in_progress issue sits in In progress and says `blocked by N` on
 42	// its card instead of looking unstarted.
 43	func columnOf(card row) column {
 44		switch {
 45		case card.status == model.StatusClosed:
 46			return colClosed
 47		case card.status == model.StatusInProgress:
 48			return colInProgress
 49		case card.blockedBy > 0:
 50			return colBlocked
 51		}
 52		return colReady
 53	}
 54	
 55	// boardCards sets the narrowed rows out in their columns.
 56	//
 57	// Ready, Blocked and In progress come from the list's own row set, in the
 58	// CLI's order, and Closed comes from core's closed read, most recently closed
 59	// first. Neither is re-sorted. A closed row the list holds under `C` is
 60	// skipped rather than placed, because it arrives in the QUEUE's order and
 61	// Closed's order is core's.
 62	func (m *Model) boardCards() [columnCount][]row {
 63		var cards [columnCount][]row
 64		for _, card := range m.narrow(m.all) {
 65			if card.status == model.StatusClosed {
 66				continue
 67			}
 68			cards[columnOf(card)] = append(cards[columnOf(card)], card)
 69		}
 70		for _, card := range m.narrow(m.closed) {
 71			cards[columnOf(card)] = append(cards[columnOf(card)], card)
 72		}
 73		return cards
 74	}
 75	
 76	// shownColumns is how many columns fit a board this wide at minColumnWidth,
 77	// separators included, and never fewer than one.
 78	func shownColumns(boardWidth int) int {
 79		return max(1, min(columnCount, (boardWidth+1)/(minColumnWidth+1)))
 80	}
 81	
 82	// firstColumn is the leftmost column on screen once the focused column has
 83	// been scrolled into view, from whichever side it went off.
 84	func firstColumn(first, focused, shown int) int {
 85		if focused < first {
 86			first = focused
 87		}
 88		if focused >= first+shown {
 89			first = focused - shown + 1
 90		}
 91		return max(0, min(first, columnCount-shown))
 92	}
 93	
 94	// pageBoard keeps the focused column on screen at the current width.
 95	func (m *Model) pageBoard() {
 96		m.first = firstColumn(m.first, int(m.focus), shownColumns(m.geo().listWidth))
 97	}
 98	
 99	// cardLines is how many lines a card takes, and cardsFit how many whole cards
100	// a column shows under its heading, a blank line between each.
101	const cardLines = 3
102	
103	func cardsFit(rows int) int { return max(rows/(cardLines+1), 1) }
104	
105	// cardTop is the first card a column shows so the selected one is on screen.
106	// It is derived from the selection rather than held, like the list's window.
107	func cardTop(selected, fit int) int { return max(0, selected-fit+1) }
108	
109	// switchColumn is `tab` and `shift+tab`: step one column, wrapping round all
110	// four, and land on the card at the same row position on screen, or the last
111	// card above it. The cursor moved, so the follow trail goes with it.
112	func (m *Model) switchColumn(step int) error {
113		fit := cardsFit(m.geo().rows)
114		offset := m.cursor.position - cardTop(m.cursor.position, fit)
115		m.focus = column((int(m.focus) + step + columnCount) % columnCount)
116		m.pageBoard()
117		m.clearFollow()
118		m.cursor.move(m.current(), offset)
119		return m.showDetail(m.cursor.id)
120	}
121	
122	// toggleBoard is `B`. It reads nothing: the board's rows are loaded with the
123	// list's, and everything that narrows or trails — the cursor's id, `/`, `a`,
124	// `r`, the follow stack — is the model's rather than a view's, so it is
125	// already there. The right pane is redrawn from the view it already holds at
126	// the new pane width.
127	//
128	// The one read `B` can cause is the list's own rule applying: a closed card
129	// is not a list row with `C` off, so going back puts the cursor on the row
130	// that held its place, and a different issue is a page read like any other.
131	func (m *Model) toggleBoard() error {
132		m.board = !m.board
133		m.resize()
134		m.place()
135		target := m.cursor.id
136		if len(m.stack) > 0 {
137			target = m.detailID
138		}
139		if target != "" && target == m.detailID {
140			return m.display(target, m.detailView)
141		}
142		return m.showDetail(target)
143	}
144	
145	// age is how long ago a moment was, in the prototype's buckets: minutes under
146	// an hour, hours under two days, days under sixty, months under a year, then
147	// years.
148	func age(elapsed time.Duration) string {
149		const day = 24 * time.Hour
150		switch {
151		case elapsed < time.Hour:
152			return fmt.Sprintf("%dm", max(int(elapsed.Minutes()), 0))
153		case elapsed < 48*time.Hour:
154			return fmt.Sprintf("%dh", int(elapsed.Hours()))
155		case elapsed < 60*day:
156			return fmt.Sprintf("%dd", int(elapsed/day))
157		case elapsed < 365*day:
158			return fmt.Sprintf("%dmo", int(elapsed/(30*day)))
159		}
160		return fmt.Sprintf("%dy", int(elapsed/(365*day)))
161	}
162	
163	// since is the moment a card's age counts from, which depends on the column:
164	// how long it has waited (Ready, Blocked), been under way (In progress), or
165	// been finished (Closed). A moment the issue lacks falls back to its creation.
166	func since(card row, col column) *model.Timestamp {
167		moment := card.created
168		switch col {
169		case colInProgress:
170			moment = card.started
171		case colClosed:
172			moment = card.closedAt
173		}
174		if moment == nil {
175			return card.created
176		}
177		return moment
178	}
179	
180	// card is one card's three lines, unstyled, none wider than width.
181	//
182	//  1. the status mark, priority, type and id, with the age flush right;
183	//  2. the title;
184	//  3. whichever of `@assignee` and `blocked by N` are present.
185	//
186	// Geometry lives here rather than in render, like the list's row, and the
187	// primitives are render's.
188	func card(candidate row, col column, width int, now time.Time) [cardLines]string {
189		head := fmt.Sprintf("%s P%d %s %s", render.StatusMark(candidate.status, candidate.tombstoned),
190			candidate.priority, candidate.kind, candidate.id)
191		when := ""
192		if moment := since(candidate, col); moment != nil {
193			if at, err := moment.Time(); err == nil {
194				when = age(now.Sub(at))
195			}
196		}
197	
198		var facts []string
199		if candidate.assignee != "" {
200			facts = append(facts, "@"+candidate.assignee)
201		}
202		if candidate.blockedBy > 0 {
203			facts = append(facts, fmt.Sprintf("blocked by %d", candidate.blockedBy))
204		}
205		return [cardLines]string{
206			flush(head, when, width),
207			render.Ellipsis(candidate.title, width),
208			render.Ellipsis(strings.Join(facts, " · "), width),
209		}
210	}
211	
212	// flush puts right against the right edge and cuts left to what is left.
213	func flush(left, right string, width int) string {
214		if right == "" {
215			return render.Ellipsis(left, width)
216		}
217		room := width - render.Cols(right) - 1
218		if room < 1 {
219			return render.Ellipsis(right, width)
220		}
221		left = render.Ellipsis(left, room)
222		return left + strings.Repeat(" ", room-render.Cols(left)) + " " + right
223	}
