225	// heading is a column's name and count. `▸ ` marks the focused column and
226	// only that one; the others get two spaces, so names line up either way.
227	func heading(col column, count int, focused bool) string {
228		marker := "  "
229		if focused {
230			marker = "▸ "
231		}
232		return fmt.Sprintf("%s%s %d", marker, columnNames[col], count)
233	}
234	
235	// columnBody renders one column into exactly width × height. selected is the
236	// cursor's card, or -1 in a column that is not focused.
237	func columnBody(col column, cards []row, selected, width, height int, now time.Time) string {
238		focused := selected >= 0
239		title := render.Ellipsis(heading(col, len(cards), focused), width)
240		if focused {
241			title = headStyle.Render(title)
242		} else {
243			title = dimStyle.Render(title)
244		}
245		lines := []string{title}
246	
247		fit := cardsFit(height)
248		top := cardTop(max(selected, 0), fit)
249		for index := top; index < len(cards) && index < top+fit; index++ {
250			if index > top {
251				lines = append(lines, "")
252			}
253			for _, line := range card(cards[index], col, width, now) {
254				// Padded before styling, so reverse video covers the card's
255				// whole width rather than stopping at its text.
256				line += strings.Repeat(" ", max(0, width-lipgloss.Width(line)))
257				switch {
258				case focused && index == selected:
259					line = cursorStyle.Render(line)
260				case cards[index].status == model.StatusClosed:
261					line = dimStyle.Render(line)
262				}
263				lines = append(lines, line)
264			}
265		}
266		return pad(strings.Join(lines, "\n"), width, height)
267	}
268	
269	// boardBody is the columns on screen, side by side with a dim `│` between,
270	// exactly width × height. The last column takes what integer division left.
271	func (m *Model) boardBody(width, height int) string {
272		shown := shownColumns(width)
273		first := firstColumn(m.first, int(m.focus), shown)
274		columnWidth := max((width-(shown-1))/shown, 1)
275		now := m.now()
276	
277		blocks := make([][]string, 0, shown)
278		for index := first; index < first+shown; index++ {
279			col := column(index)
280			w := columnWidth
281			if index == first+shown-1 {
282				w = max(width-(shown-1)-(shown-1)*columnWidth, 1)
283			}
284			selected := -1
285			if col == m.focus {
286				selected = m.cursor.position
287			}
288			blocks = append(blocks, strings.Split(columnBody(col, m.cards[col], selected, w, height, now), "\n"))
289		}
290	
291		separator := dimStyle.Render("│")
292		lines := make([]string, 0, height)
293		for line := range height {
294			parts := make([]string, 0, len(blocks))
295			for _, block := range blocks {
296				parts = append(parts, block[line])
297			}
298			lines = append(lines, strings.Join(parts, separator))
299		}
300		return pad(strings.Join(lines, "\n"), width, height)
301	}
302	
303	// boardTitle names the scope, and says how many columns are off screen on
304	// each side while any are.
305	func (m *Model) boardTitle(width int) string {
306		title := m.listTitle()
307		shown := shownColumns(width)
308		if shown < columnCount {
309			first := firstColumn(m.first, int(m.focus), shown)
310			title += fmt.Sprintf(" · ◀ %d · %d ▶", first, columnCount-first-shown)
311		}
312		return title
313	}
314	
315	// boardCount is how many cards the board shows.
316	func (m *Model) boardCount() int {
317		total := 0
318		for _, cards := range m.cards {
319			total += len(cards)
320		}
321		return total
322	}
323	
324	// boardLoaded is how many cards the board would show with nothing narrowing:
325	// the live rows and core's closed rows, each once.
326	func (m *Model) boardLoaded() int {
327		total := len(m.closed)
328		for _, candidate := range m.all {
329			if candidate.status != model.StatusClosed {
330				total++
331			}
332		}
333		return total
334	}
